const mysql = require('mysql2/promise');

async function main() {
  const pool = mysql.createPool({
    host: process.env.DB_HOST, user: process.env.DB_USER,
    password: process.env.DB_PASSWORD, database: process.env.DB_NAME
  });
  const list = [['Asha', 85], ['Bala', 72], ['Chandan', 90]];

  const [ins] = await pool.query(
    'INSERT INTO students (name, marks) VALUES ?', [list]);
  console.log(ins.affectedRows, ins.insertId);

  const [rows] = await pool.query(
    'SELECT name FROM students WHERE marks >= ?', [80]);
  console.log(rows.length, rows.map(r => r.name).join(','));

  const [upd] = await pool.query(
    'UPDATE students SET marks = marks + 5 WHERE id = ?', [11]);
  console.log(upd.affectedRows, upd.changedRows);
  await pool.end();
}
main();
